// Estrae le recensioni senza risposta
const config = $('Config cliente').first().json;
const reviews = $json.reviews || [];
const starMap = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
const out = [];
for (const r of reviews) {
  if (r.reviewReply && r.reviewReply.comment) continue; // gia' risposta
  out.push({
    json: {
      config,
      review_id: r.reviewId || (r.name || '').split('/').pop(),
      review_name: r.name,
      reviewer: (r.reviewer && r.reviewer.displayName) || 'Cliente',
      stars: starMap[r.starRating] || 0,
      comment: r.comment || '',
    },
  });
}
return out;

const r = $json;
const c = r.config;

const system = `Rispondi alle recensioni Google per ${c.nome_cliente} (${c.settore} a ${c.citta}). Suona umano e personale, MAI aziendale o robotico. Cita dettagli specifici della recensione quando ci sono. Inserisci in modo naturale una keyword locale (es. "${c.settore} a ${c.citta}") quando la risposta lo permette senza forzature — aiuta il ranking su Maps. Massimo 80 parole. Niente emoji nelle risposte a recensioni negative; al massimo una in quelle positive.`;

let istruzioni;
if (r.stars >= 4) {
  istruzioni = 'Recensione POSITIVA: ringrazia con calore, cita un dettaglio della loro esperienza, invita a tornare o a consigliare l\'attivita\'.';
} else if (r.stars === 3) {
  istruzioni = 'Recensione TIEPIDA: ringrazia, riconosci il margine di miglioramento, invita a ricontattare per sistemare le cose.';
} else {
  istruzioni = 'Recensione NEGATIVA: scusati con sincerita\' senza ammettere colpe legali, mostra che il problema viene preso sul serio, sposta la conversazione in privato (invita a chiamare o scrivere). Tono calmo e professionale.';
}

const prompt = `${istruzioni}\n\nRecensione di ${r.reviewer} (${r.stars} stelle):\n"${r.comment || '(nessun testo, solo stelle)'}"\n\nScrivi SOLO il testo della risposta, senza virgolette ne' premesse.`;

return {
  json: {
    ...r,
    anthropic_request: {
      model: 'claude-opus-4-8',
      max_tokens: 512,
      system,
      messages: [{ role: 'user', content: prompt }],
    },
  },
};

const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
const r = $('Prepara risposta').item.json;
return { json: { ...r, reply_text: text } };

